app("go-runner", "Rooftop Dash", "Game", "Tap to jump between buildings", "Run across a city skyline and leap the gaps between roofs.", "Tap or press BOOT to jump, tap again in the air for a double jump. The city speeds up the longer you last, and your best distance is saved.", [GOTCHI, SOUND, FOREVER], ("#3b2a7a", "#120c30"))
app("go-botface", "Bot Buddy", "Companion", "A face that looks back at you", "A little robot face that follows your finger and has moods.", "Touch the screen and the eyes follow. Tap to change mood between happy, sleepy, surprised, grumpy and in love. Shake it and it gets dizzy.", [GOTCHI, "Accelerometer for the dizzy trick"], ("#123a4a", "#07121c"), tilt=True)
app("go-stackdrop", "Stack Drop", "Game", "Shapes of three and four cells", "Fit falling shapes into full lines before the well fills up.", "Tap left or right to move, the middle to turn, swipe down to drop. The set mixes small three-cell pieces in with the bigger ones, and it gets faster as you clear lines.", [GOTCHI, SOUND, FOREVER], ("#17406b", "#0a1420"))
app("go-party", "Party Pack", "Game", "Hot Bomb, Quick Draw, Tap Race", "Three quick games for a group passing one Gotchi around.", "Hot Bomb: pass it on before the hidden fuse runs out. Quick Draw: two players, first to tap when the screen goes green. Tap Race: ten seconds, left side against right. BOOT returns to the menu.", ["One Gotchi and some friends", SOUND], ("#6b2a7a", "#22102e"))
app("go-synth", "Pocket Synth", "Audio", "Two octaves under your thumbs", "Play a touch keyboard with four sounds.", "Two octaves of keys with soft, buzzy, flute and noise sounds, and an octave shift on the plus and minus buttons. Slide along the keys to glide. One note plays at a time.", ["Needs the speaker"], ("#6b3a1a", "#1c1008"))
app("go-noodle", "Noodle", "Game", "Swipe to steer, do not tangle", "Steer a growing noodle to the dumplings.", "Swipe to turn, or use the volume keys to turn left and right. Every dumpling makes you longer and faster. Do not hit the walls or yourself.", [GOTCHI, SOUND, FOREVER], ("#1f5a4a", "#0a1c18"))
app("go-blobpal", "Blob Pal", "Companion", "Hatch it, feed it, play with it", "Raise a little blob from an egg to fully grown.", "Warm the egg until it hatches, then feed it, play ball, put it to bed and clean up after it. Its food, joy, rest and age are saved on the Gotchi. Time only passes while the app is open, because apps cannot read a real clock.", [GOTCHI, SOUND, "Saves your pet on the Gotchi"], ("#2a7a5a", "#0e2a24"), shot=150)
app("go-kaleido", "Kaleido", "Art", "Twelve mirrors, always moving", "A drifting kaleidoscope you can stir with a finger.", "Drag to spin the pattern, tap for new colours and shapes, press BOOT to freeze the frame.", [GOTCHI], ("#3a1a6b", "#0c0620"))
app("go-coderain", "Code Rain", "Art", "Rain, glitch and retro bars", "Falling glyphs and broken-signal screensavers.", "Three moving screens: green falling code, a signal glitch and retro colour bars. Tap to change between them.", [GOTCHI], ("#0a3a20", "#020e08"))
app("go-beatgrid", "Beat Grid", "Audio", "4 tracks, 16 steps", "A step drum machine with a beat already loaded.", "Tap cells to place kick, snare, hat and blip hits, then press Play. Change the tempo with the plus and minus buttons from 60 to 200 BPM. It uses the Gotchi tone generator, so stacked hits may share one voice.", ["Needs the speaker"], ("#5a2a10", "#1a0d06"))
app("go-marble", "Marble Run", "Game", "A new maze every level", "Tilt the Gotchi to roll a marble through a maze to the hole.", "Every level is a freshly generated maze. If you do not want to tilt, hold your finger on the screen and the marble rolls toward it. BOOT makes a new maze.", [ACC, "Touch works too"], ("#5a3a1a", "#1a1006"), tilt=True)
app("go-brickbash", "Brick Bash", "Game", "Drag, tilt or press keys", "Bounce a ball through walls of coloured bricks.", "Drag the paddle, tilt the Gotchi, or use the volume keys. Three lives, and each level has a new brick pattern. Tap to serve.", [GOTCHI, SOUND, FOREVER], ("#6b1a3a", "#200810"), tilt=True)
app("go-dicecup", "Dice Cup", "Tool", "Tap or shake to roll", "Roll one to six dice and see the total.", "Tap or shake to roll, and use plus and minus to change how many dice are in the cup. Handy for board games when the dice have gone missing.", [GOTCHI, "Accelerometer for shake to roll"], ("#14523a", "#061a12"), tilt=True)
app("go-voicefx", "Silly Voice", "Audio", "Chipmunk, giant, robot, backward", "Record three seconds and hear it four silly ways.", "Hold the top bar and talk, then pick an effect to play it back changed. There are also four sound effect buttons. Your recording stays in memory only and goes when you close the app.", [MIC, "Needs the speaker"], ("#4a1a7a", "#160826"))
app("go-level", "Level Pro", "Tool", "Bubble, angle, motion", "A bubble level, an edge angle gauge and a motion meter.", "Lay it flat for the bubble, stand it on an edge for the angle, or watch the motion meter count shakes. Tap to switch and press BOOT to set zero on a known surface. Use it for hanging pictures, not for building a house.", [ACC], ("#2a5a1a", "#0c1a08"), tilt=True)
app("go-boxer", "Shake Boxer", "Game", "Flick to punch, tilt to dodge", "Box a trainer by flicking the Gotchi when the guard drops.", "Punch by flicking the Gotchi or tapping when it says OPEN. When a glove is coming, lean the way it tells you. Volume keys dodge if you would rather not lean.", [ACC, SOUND, FOREVER], ("#7a2a1a", "#240c08"), tilt=True)
app("go-orb", "Answer Orb", "Toy", "Ask, shake, read", "Ask a question out loud, then shake or tap for an answer.", "A glowing orb gives one of twenty-two answers written just for it. Do not make serious decisions with it.", [GOTCHI, "Accelerometer for shake"], ("#3a1a8a", "#0e0626"), tilt=True, shot=20)
app("go-focus", "Focus Timer", "Tool", "Work and break rounds", "A work and break timer with a ring that counts down.", "Pick 25/5, 50/10 or 15/3 minutes. Tap the ring to start or pause, and it chimes at the end of each round. Finished rounds are counted and saved. Volume keys add or remove a minute.", [GOTCHI, "Speaker for the chime"], ("#6b2a2a", "#1e0c0c"), shot=20)
app("go-paddle", "Paddle Duel", "Game", "First to seven", "Paddle tennis for two thumbs, or against the computer.", "Tap the left half at the start to play the computer or the right half for two players. Each player drags on their own side of the screen. The ball speeds up with every return.", ["Two players or just you", SOUND], ("#123a6b", "#061020"))
app("go-fortune", "Fortune Cards", "Toy", "A deck of our own", "Draw three cards for what was, what is and what comes next.", "A 22-card deck written and drawn just for this app. Tap to turn a card, tap again to read it. For fun only.", [GOTCHI], ("#4a1a6b", "#160826"), shot=600)
app("go-tempo", "Tempo Tuner", "Tool", "Metronome and note finder", "A metronome with tap tempo and a tuner that names your note.", "Set the speed with plus and minus or tap in time. The tuner listens through the microphone and shows the nearest note and how sharp or flat you are. Check it against a real tuner before a concert.", [MIC, "Needs the speaker"], ("#1a3a6b", "#081020"))
app("go-casino", "Lucky Lounge", "Game", "Play chips only", "Slots, high or low and a spin wheel with play chips.", "Three small table games sharing one chip pile. Chips refill for free when you run out. There is nothing to buy and nothing to win.", [GOTCHI, SOUND, "Keeps your chips on the Gotchi"], ("#14503a", "#061a12"))
app("go-tiles", "Beat Tiles", "Game", "Tap on the line", "Tap the four lanes as tiles reach the line and play a tune.", "Each hit plays the next note of one of three tunes written for this app. Six misses ends the song and the speed keeps climbing.", [GOTCHI, "Needs the speaker", FOREVER], ("#2a1a6b", "#0c0822"))
app("go-board", "Board Buddies", "Game", "Three board games, one Gotchi", "Three in a row, drop four and flip field against the Gotchi.", "Three classic style board games with a computer opponent that blocks your wins and likes corners. BOOT goes back to the menu. Two Gotchis cannot play each other yet.", [GOTCHI], ("#1f3a6b", "#0a1224"))
app("go-puffhop", "Puff Hop", "Game", "Tap to flutter", "Flutter a puffball through the gaps.", "Tap to flap upward. The gaps come faster as your score climbs, and one bump ends the run.", [GOTCHI, SOUND, FOREVER], ("#2a7aa0", "#0e2a3a"))
app("go-forge", "Coin Forge", "Game", "Tap, buy, repeat", "Tap to mint coins and buy machines that mint for you.", "Four kinds of helpers keep producing while the app is open, and everything is saved. Apps cannot run when closed, so it does not earn while the Gotchi is off.", [GOTCHI, "Saves your forge on the Gotchi"], ("#6b4a14", "#1e1406"))
app("go-petri", "Petri", "Simulation", "Paint cells and watch them live", "Paint living cells and watch them spread, die and settle.", "Classic life rules on a wrapping 74 by 56 world. Draw with your finger, BOOT pauses, VOL+ changes speed and VOL- reseeds.", [GOTCHI], ("#123a4a", "#06121a"))
app("go-echocave", "Echo Cave", "Game", "A short text adventure", "Choose your way through a cave of fights and treasure.", "A compact choose your path story with health, gold and one important lantern. It takes about five minutes to finish.", [GOTCHI], ("#2a1e4a", "#0c0816"))
app("go-fiveguess", "Five Guess", "Game", "Six tries, five letters", "Find the hidden five-letter word in six tries.", "Green means right place, yellow means wrong place. It has about a hundred words of its own and accepts any five letters as a guess, because a full dictionary will not fit.", [GOTCHI], ("#2a5a3a", "#0c1a12"))
app("go-merge", "Merge Cubes", "Game", "Swipe and double up", "Slide the board to merge equal numbers.", "Swipe in any direction and matching numbers combine. Your best score is saved.", [GOTCHI, SOUND, FOREVER], ("#6b3a5a", "#1e0e1a"))
app("go-tilepairs", "Tile Pairs", "Game", "Every deal can be solved", "Clear a two-layer table by matching free tiles.", "A tile is free when nothing sits on it and one side is open. Each table is dealt in reverse from a solved position, so it can always be cleared, but your choices can still get you stuck.", [GOTCHI], ("#14503a", "#061a12"))
app("go-tunnel", "Tunnel Pilot", "Game", "Tilt through the gates", "Fly through gates as the tunnel rushes at you.", "A small flight game drawn as flat rings. Tilt to steer, or drag if you prefer. Miss three gates and it is over. This is an arcade game, not a real flight simulator.", [ACC, SOUND, FOREVER], ("#123070", "#060e24"), tilt=True)
app("go-starpatrol", "Star Patrol", "Game", "Your ship fires by itself", "Clear wave after wave of incoming ships.", "Drag, tilt or use the volume keys to move. Your ship fires by itself and the waves get faster.", [GOTCHI, SOUND, FOREVER], ("#1a2a6b", "#080c22"), tilt=True)
app("go-ninegrid", "Nine Grid", "Game", "Easy, medium, hard", "Fill every row, column and box with 1 to 9.", "Tap a square, then a number. Mistakes turn red. BOOT changes difficulty and deals a new puzzle. Some puzzles can have more than one answer, and any valid answer counts.", [GOTCHI], ("#5a5240", "#1c1a14"))
app("go-minepatrol", "Mine Patrol", "Game", "Your first tap is always safe", "Open the field without touching a mine.", "26 mines hidden in a 16 by 11 field, shown as coloured dots that count nearby mines. Turn on Flag to mark squares.", [GOTCHI, SOUND], ("#3a4658", "#10141c"))
app("go-pondcast", "Pond Cast", "Game", "Cast, wait, reel", "Cast a line, wait for the dip and reel without snapping it.", "Six fish to catch, from small minnows to one very old whiskered giant. Hold to reel and let go when the tension gets too high.", [GOTCHI, SOUND, "Keeps your catch count"], ("#2a6a9a", "#0c2436"))
app("go-cannonhill", "Cannon Hill", "Game", "Pull back and fire", "Lob shells over the hills at the computer's cannon.", "Pull back to aim, let go to fire, watch the wind, and blast craters in the hill. Three hits wins.", [GOTCHI, SOUND], ("#3a6a3a", "#122212"))
app("go-gateguard", "Gate Guard", "Game", "Build, upgrade, hold the road", "Build towers along the road and stop the waves.", "Three tower types: Bolt for steady damage, Frost to slow, Bomb for groups. Tap a pad to build or upgrade, then press Next wave.", [GOTCHI, SOUND, FOREVER], ("#2a5a3a", "#0c1a12"))
app("go-radar", "Treasure Radar", "Toy", "It does not detect anything", "A sweeping radar prop with a hot and cold game.", "Blips appear on the sweep for fun. Tap the screen to hunt the hidden spot and it tells you hot or cold. It is a prop. It does not sense anything real.", [GOTCHI, SOUND], ("#0a4a2a", "#02140c"), tilt=True)
app("go-calc", "Calculator", "Tool", "The everyday kind", "Add, subtract, multiply, divide, percent and sign.", "A simple calculator with big buttons. It works with ordinary decimal arithmetic, so very long results get rounded.", [GOTCHI], ("#3a3a4a", "#101018"))
app("go-devinfo", "Gotchi Info", "Tool", "Battery, power and sensors", "See battery, charging, uptime, tilt and sound level at once.", "A one screen health check for your Gotchi. Handy for testing a new unit.", ["Reads the battery and microphone"], ("#1a3a5a", "#081420"), tilt=True)
app("go-ambient", "Calm Sounds", "Audio", "Rain, ocean, wind, fire", "Rain, ocean, wind and fire made live on the Gotchi.", "All four sounds are generated by the app rather than played from recordings, so they never loop. Set a 15, 30 or 60 minute sleep timer.", ["Needs the speaker"], ("#1a3a6b", "#081224"), shot=150)
app("go-vubars", "VU Bars", "Audio", "A needle and sixteen bars", "A needle meter and live sound bars from the microphone.", "Shows how loud it is and where the sound sits from bass to treble. Nothing is recorded or sent anywhere. For a finer view, Spectrum Analyzer has more bands.", [MIC], ("#1a2a4a", "#080e1c"))
app("go-notes", "Quick Notes", "Tool", "Eight short notes", "Type up to eight short notes on the screen keyboard.", "Tap New note and type, tap a note twice to edit it. Notes stay on the Gotchi until you delete them.", [GOTCHI, "Saves notes on the Gotchi"], ("#7a6a2a", "#2a240c"), shot=20)
app("go-orbits", "Gravity Garden", "Toy", "Flick planets around a star", "Launch planets and watch them orbit, slingshot and crash.", "Drag back and let go to launch. Simple gravity toward one star does the rest. BOOT clears the sky.", [GOTCHI], ("#141a4a", "#060818"))
app("go-flipbook", "Flip Book", "Toy", "Six frames, one finger", "Draw six frames and play them back as a little animation.", "Each frame shows a faint copy of the one before it. Your drawings stay on the Gotchi. It plays only the animations you draw, because apps cannot load video files.", [GOTCHI, "Saves drawings on the Gotchi"], ("#5a4a7a", "#1a1426"))
app("go-tinytasks", "Tiny Tasks", "Tool", "Tick it off", "A short to-do list you tick off with a tap.", "Up to ten tasks typed on the screen keyboard. Tap to tick, tap the x to remove.", [GOTCHI, "Saves tasks on the Gotchi"], ("#1a4a4a", "#081818"), shot=20)
app("go-namebadge", "Name Tag", "Tool", "Hello, I am you", "Wear your name in big letters at meetups.", "Type your name and a line about yourself once, then tap to change between four looks.", [GOTCHI, "Saves your name on the Gotchi"], ("#8a2a2a", "#2a0c0c"))
app("go-morse", "Morse Trainer", "Tool", "Dots, dashes, streaks", "See a letter, key it with short and long presses.", "A short press is a dot and a long press is a dash. Wait a moment and it checks your answer. Press a volume key for a hint.", [GOTCHI, "Needs the speaker", FOREVER], ("#0f4a3f", "#051a16"))
app("go-abc", "ABC Buddy", "Learning", "A for Apple, and a quiz", "Learn letters with pictures, then play find the letter.", "Twenty-six letters with simple drawn pictures and a quiz mode for little ones. It does not speak the words, because the app has no recordings.", [GOTCHI, SOUND], ("#c07a30", "#3a240e"))
app("go-sixlines", "Six Lines", "Toy", "A simple coin reading", "Toss coins six times to build a figure and read its trigrams.", "Inspired by coin divination from the I Ching. It reads only the upper and lower trigrams, with short lines written for this app. A bit of fun, not a full reading.", [GOTCHI, "Accelerometer for shake"], ("#4a3018", "#180e06"), tilt=True)
app("go-pixelpad", "Pixel Pad", "Art", "Eight colours, tiny canvas", "Paint tiny pixel art with your finger.", "A 32 by 34 canvas with eight colours. Your picture saves itself on the Gotchi.", [GOTCHI, "Saves your picture on the Gotchi"], ("#3a3a5a", "#10101c"))
app("go-julia", "Julia Drift", "Art", "A fractal that keeps changing", "A fractal that slowly changes shape as you watch.", "Drag to steer its shape, tap for new colours. Drawn in chunky 8 pixel blocks so it can keep moving.", [GOTCHI], ("#3a1a8a", "#0e0626"))
app("go-memo", "Memo", "Audio", "Eight seconds, kept in memory", "Hold to record eight seconds, tap to hear it back.", "A very small voice memo. The recording stays in memory only and goes when you close the app. For 20 seconds at better quality, use Voice Recorder.", [MIC, "Needs the speaker"], ("#5a1a2a", "#1c080e"))
app("go-scope", "Scope", "Tool", "See your voice", "See the sound wave from the microphone.", "A simple oscilloscope view of the microphone only. Tap to freeze, volume keys change gain, and the bottom bar changes the time scale. It is not a measuring instrument.", [MIC], ("#0a4a30", "#02140e"))
app("go-sandglass", "Sand Glass", "Toy", "Real falling grains", "Watch real grains of sand fall through a glass.", "Each grain is simulated. Turn the Gotchi over and it runs the other way, or lean it and the sand piles to one side. Tap to refill. It is a toy, not a precise timer.", [ACC], ("#5a3a10", "#1c1206"), tilt=True, shot=20)
app("go-cardcoach", "Card Coach", "Learning", "Capitals, tables, Hindi numbers", "Flash cards where the ones you miss come back sooner.", "Three built-in decks. Tap to turn a card over, then say if you knew it. Hindi numbers are written in English letters, because the Gotchi font has no Hindi characters.", [GOTCHI], ("#1f3a6b", "#0a1224"))
app("go-makercalc", "Maker Calc", "Tool", "Resistors, Ohm's law, LEDs", "Resistor colour bands, Ohm's law and LED resistor sums.", "Tap the bands to read a resistor, change voltage and current to get resistance, or work out the resistor for an LED. Double check anything you are going to power up.", [GOTCHI], ("#3a4a2a", "#10160c"))
app("go-lapclock", "Lap Clock", "Tool", "Stopwatch and intervals", "A stopwatch with laps and an interval timer for workouts.", "Lap times show the last four. Intervals switch between work and rest with a beep each time.", [GOTCHI, SOUND], ("#1a3a5a", "#081420"))
app("go-tally", "Tally", "Tool", "Four big counters", "Four big counters for scores, stock or anything.", "Tap to add one and use the small minus to take one back. BOOT clears all four. Counts stay on the Gotchi.", [GOTCHI, SOUND, "Saves your counts on the Gotchi"], ("#6b2a3a", "#200c12"))
